(()=>{'use strict';if(window.__qpuDbList)return;window.__qpuDbList=true;let busy=false,last=0;
const rows=x=>Array.isArray(x)?x:Array.isArray(x?.data)?x.data:Array.isArray(x?.rows)?x.rows:[];
async function load(force=false){const page=document.querySelector('#purchase'),body=page?.querySelector('.module-shell>.module-body tbody');if(!body||busy||(!force&&Date.now()-last<12000))return;busy=true;last=Date.now();let info=page.querySelector('.qpu-db-message');if(!info){info=document.createElement('small');info.className='qpu-db-message';info.style.cssText='display:block;padding:6px 14px;color:#526a83';body.closest('.module-body').before(info)}try{const res=await fetch('/api/purchase-orders',{credentials:'include',cache:'no-store'});const x=await res.json();if(!res.ok||x?.success===false)throw Error(x?.message||'서버 응답 '+res.status);const data=rows(x);body.replaceChildren();data.forEach((p,i)=>{const tr=document.createElement('tr');tr.dataset.orderNumber=String(p.purchaseNo||p.no||'');[i+1,p.orderDate||'',p.supplier||'',p.item||p.material||'',p.qty??'',p.requestedDueDate||p.due||'',p.status||'',p.iqcStatus||p.iqc||''].forEach(v=>{const td=document.createElement('td');td.textContent=String(v);tr.append(td)});body.append(tr)});info.textContent=data.length?'DB 등록 구매발주 '+data.length+'건':'등록된 구매발주 내역이 없습니다. 수입검사 가져오기에서 확인 후 등록하세요.'}catch(e){info.textContent='구매발주 DB 조회 불가: '+e.message}finally{busy=false}}
document.addEventListener('click',e=>{if(e.target.closest?.('#qpu-import-dialog .qpi-save'))setTimeout(()=>load(true),1500);if(e.target.closest?.('#purchase .qpu-search,#purchase .qpu-clear'))setTimeout(()=>load(true),300)},true);
new MutationObserver(()=>{const p=document.querySelector('#purchase');if(p?.querySelector('.module-shell>.module-body tbody')&&!p.querySelector('.qpu-db-message'))load()}).observe(document.body,{childList:true,subtree:true});load();
})();